//! C++ iostream default double formatting (`std::cout << value`, precision 6,
//! default float format == printf "%g" semantics).
//!
//! IMPLEMENTATION CONTRACT (fixed — the crate root calls this exact signature):
//!   pub fn format_cpp_f64(v: f64) -> String

/// Format a double exactly like C++ `std::cout << v` with default settings,
/// i.e. printf("%g", v): 6 significant digits, round-half-to-even, scientific
/// notation when the (post-rounding) decimal exponent is < -4 or >= 6,
/// otherwise fixed notation with trailing fractional zeros stripped.
pub fn format_cpp_f64(v: f64) -> String {
    if v.is_nan() {
        return "nan".to_string();
    }
    if v.is_infinite() {
        return if v > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }

    // "{:.5e}" yields "[-]d.ddddde[-]X" with correctly rounded
    // (round-half-to-even) 6 significant digits.
    let s = format!("{:.5e}", v);
    let (mantissa, exp_str) = s.split_once('e').unwrap();
    let exp: i32 = exp_str.parse().unwrap();

    let (sign, mantissa) = match mantissa.strip_prefix('-') {
        Some(rest) => ("-", rest),
        None => ("", mantissa),
    };
    // mantissa is "d.ddddd"; collect the 6 significant digits.
    let digits: Vec<u8> = mantissa.bytes().filter(|b| b.is_ascii_digit()).collect();
    debug_assert_eq!(digits.len(), 6);

    if !(-4..6).contains(&exp) {
        // Scientific notation: strip trailing zeros from the mantissa fraction.
        let mut frac: &[u8] = &digits[1..];
        while let Some((&b'0', rest)) = frac.split_last() {
            frac = rest;
        }
        let mut out = String::new();
        out.push_str(sign);
        out.push(digits[0] as char);
        if !frac.is_empty() {
            out.push('.');
            out.push_str(std::str::from_utf8(frac).unwrap());
        }
        out.push('e');
        if exp < 0 {
            out.push('-');
        } else {
            out.push('+');
        }
        let abs_exp = exp.unsigned_abs();
        if abs_exp < 10 {
            out.push('0');
        }
        out.push_str(&abs_exp.to_string());
        return out;
    }

    // Fixed notation: value == digits * 10^(exp - 5).
    let mut out = String::new();
    out.push_str(sign);
    if exp >= 0 {
        let int_len = (exp + 1) as usize;
        for &d in &digits[..int_len.min(digits.len())] {
            out.push(d as char);
        }
        // Pad with zeros when the integer part extends past the 6 digits.
        for _ in digits.len()..int_len {
            out.push('0');
        }
        let mut frac: &[u8] = if int_len < digits.len() { &digits[int_len..] } else { &[] };
        while let Some((&b'0', rest)) = frac.split_last() {
            frac = rest;
        }
        if !frac.is_empty() {
            out.push('.');
            out.push_str(std::str::from_utf8(frac).unwrap());
        }
    } else {
        // 0.000ddd: -exp - 1 leading zeros after the decimal point.
        out.push_str("0.");
        for _ in 0..(-exp - 1) {
            out.push('0');
        }
        let mut frac: &[u8] = &digits;
        while let Some((&b'0', rest)) = frac.split_last() {
            frac = rest;
        }
        out.push_str(std::str::from_utf8(frac).unwrap());
    }
    out
}

#[path = "/output/fmt.rs"]
mod fmt;

use std::process::Command;

fn printf_g(v: f64) -> String {
    // bash builtin printf supports %g
    let out = Command::new("bash")
        .arg("-c")
        .arg(format!("printf '%g' '{}'", v))
        .output()
        .unwrap();
    String::from_utf8(out.stdout).unwrap()
}

fn main() {
    let mut vals: Vec<f64> = vec![
        3462040.0, 8514.5, 0.0, -0.0, 999999.5, 0.0000123456789, 123456.0,
        1234567.0, 100000.0, -42.5, 1000000.5, 99999.5, 5000.0, 0.25,
        1.0, -1.0, 0.0001, 0.00001, 1.5e-5, 1e6, 999999.4999999999,
        123456.5, 123455.5, 0.5, 1e-4, 9.99999e-5, 3.46204e6, 1e20,
        1e-20, 123456789.0, 0.1, 2.0 / 3.0, std::f64::consts::PI,
        1.0000005, 9.999995e5, 9.999994999999e5, 0.000123456789,
        999999500.0, 4.5e-5, 1234500.0, 1000005.0, 0.0009999995,
        123.456, -123.456, -999999.5, -1e6, -0.0000123456789,
    ];

    // a few hundred pseudo-random values across magnitudes
    let mut seed: u64 = 0x123456789abcdef;
    let mut rng = move || {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        seed
    };
    for _ in 0..500 {
        let mant = (rng() % 1_000_000_000) as f64 / 100.0;
        let exp = (rng() % 25) as i32 - 15;
        let v = mant * 10f64.powi(exp);
        vals.push(v);
        vals.push(-v);
    }
    // integers around the fixed/scientific boundary
    for base in [99999, 100000, 123456, 999999, 1000000, 9999995, 9999999] {
        for frac in [0.0, 0.4, 0.5, 0.5000001, 0.4999999] {
            vals.push(base as f64 + frac);
            vals.push(-(base as f64 + frac));
        }
    }
    // small values around the -4/-5 exponent boundary
    for &b in &[9.99999e-5, 9.999995e-5, 1.00001e-4, 9.999999e-5, 1.23456789e-4] {
        vals.push(b);
        vals.push(-b);
    }

    let mut mismatches = 0;
    for &v in &vals {
        let want = printf_g(v);
        let got = fmt::format_cpp_f64(v);
        if want != got {
            mismatches += 1;
            println!("MISMATCH v={:?} printf={:?} mine={:?}", v, want, got);
        }
    }
    println!("checked {} values, {} mismatches", vals.len(), mismatches);
}

