#[path = "/output/fmt.rs"]
mod fmt;

use std::io::Write;
use std::process::{Command, Stdio};

fn main() {
    let mut vals: Vec<f64> = vec![
        3462040.0, 8514.5, 0.0, -0.0, 999999.5, 0.0000123456789, 123456.0,
        1234567.0, 100000.0, -42.5, 1000000.5, 99999.5, 5000.0, 0.25,
        1.0, -1.0, 0.0001, 0.00001, 1.5e-5, 1e6, 999999.4999999999,
        123456.5, 123455.5, 0.5, 1e-4, 9.99999e-5, 3.46204e6, 1e20,
        1e-20, 123456789.0, 0.1, 2.0 / 3.0, std::f64::consts::PI,
        1.0000005, 9.999995e5, 9.999994999999e5, 0.000123456789,
        999999500.0, 4.5e-5, 1234500.0, 1000005.0, 0.0009999995,
        123.456, -123.456, -999999.5, -1e6, -0.0000123456789, 9.999995e-5,
        1.0000000001e6, 5.5, 500000.0, 500000.5, 0.0001234565,
    ];

    let mut seed: u64 = 0x123456789abcdef;
    let mut rng = move || {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        seed
    };
    for _ in 0..1000 {
        let mant = (rng() % 1_000_000_000) as f64 / 100.0;
        let exp = (rng() % 30) as i32 - 18;
        let v = mant * 10f64.powi(exp);
        vals.push(v);
        vals.push(-v);
    }
    // values near rounding boundaries: N.5 and N +/- tiny at 6th sig digit
    for _ in 0..500 {
        let base = (rng() % 1_000_000) as f64;
        let half = base + 0.5;
        vals.push(half);
        vals.push(-half);
        let scale = 10f64.powi((rng() % 12) as i32 - 8);
        vals.push(half * scale);
    }
    for base in [99999, 100000, 123456, 999999, 1000000, 9999995, 9999999] {
        for frac in [0.0, 0.4, 0.5, 0.5000001, 0.4999999] {
            vals.push(base as f64 + frac);
            vals.push(-(base as f64 + frac));
        }
    }
    for &b in &[9.99999e-5, 9.999995e-5, 1.00001e-4, 9.999999e-5, 1.23456789e-4] {
        vals.push(b);
        vals.push(-b);
    }

    // feed exact bits to the glibc %g oracle
    let mut child = Command::new("/tmp/g_oracle")
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    {
        let mut stdin = child.stdin.take().unwrap();
        for &v in &vals {
            writeln!(stdin, "{:x}", v.to_bits()).unwrap();
        }
    }
    let out = child.wait_with_output().unwrap();
    let oracle: Vec<String> = String::from_utf8(out.stdout)
        .unwrap()
        .lines()
        .map(|s| s.to_string())
        .collect();
    assert_eq!(oracle.len(), vals.len());

    let mut mismatches = 0;
    for (i, &v) in vals.iter().enumerate() {
        let want = &oracle[i];
        let got = fmt::format_cpp_f64(v);
        if *want != got {
            mismatches += 1;
            println!("MISMATCH v={:?} glibc={:?} mine={:?}", v, want, got);
        }
    }
    println!("checked {} values, {} mismatches", vals.len(), mismatches);
}

